import com.project.system.service.WalletService;import java.math.BigDecimal;import java.util.*;import org.springframework.context.annotation.AnnotationConfigApplicationContext;import org.springframework.jdbc.core.JdbcTemplate;
public class RechargeOrderIntegration{public static void main(String[]args){try(AnnotationConfigApplicationContext c=new AnnotationConfigApplicationContext(WalletIdentityIntegration.Config.class)){WalletService s=c.getBean(WalletService.class);JdbcTemplate db=c.getBean(JdbcTemplate.class);String key=UUID.randomUUID().toString();long id=s.trade(2,"RECHARGE",new BigDecimal("1.00"),null,null,key,1);Map<String,Object> receipt=s.receipt(id);if(!receipt.get("order_no").toString().startsWith("DD")||!receipt.get("transaction_no").toString().startsWith("CZ"))throw new AssertionError();System.out.println("PASS distinct recharge order and ledger numbers");if(s.trade(2,"RECHARGE",BigDecimal.ONE,null,null,key,1)!=id||!receipt.equals(s.receipt(id)))throw new AssertionError();System.out.println("PASS duplicate request preserves both numbers");if(db.queryForObject("select count(*) from campus_recharge_order where ledger_id=?",Integer.class,id)!=1)throw new AssertionError();System.out.println("PASS one order associated with one ledger");if(db.queryForObject("select count(*) from campus_ledger l left join campus_recharge_order o on o.ledger_id=l.id where l.kind='RECHARGE' and o.id is null",Integer.class)!=0)throw new AssertionError();System.out.println("PASS historical recharge order backfill");}}}
